<?php
/**
 * Virtual /llms.txt endpoint.
 *
 * No llms.txt generator existed anywhere in this codebase (theme or active
 * plugins) at the time this was added — the live site's llms.txt is either
 * a manually-dropped static file on the production server or generated by
 * something outside this repo. This class serves a real one locally,
 * rebuilt from live service data on every request, so it can never go
 * stale when a service's title, summary or price changes in wp-admin.
 *
 * @package Arqam-Web
 */

if ( ! defined( 'ABSPATH' ) ) exit;

class ArqamWeb_LLMs_Txt {

	/**
	 * Intercepts requests for /llms.txt (relative to the site's home path)
	 * and serves a plain-text response built from live content. Runs on
	 * template_redirect so it works with or without a rewrite-rule flush.
	 */
	public static function maybe_serve(): void {
		$request_path = trim( (string) wp_parse_url( $_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH ), '/' );
		$home_path    = trim( (string) wp_parse_url( home_url( '/' ), PHP_URL_PATH ), '/' );
		$expected     = $home_path !== '' ? $home_path . '/llms.txt' : 'llms.txt';

		if ( $request_path !== $expected ) {
			return;
		}

		status_header( 200 );
		header( 'Content-Type: text/plain; charset=utf-8' );
		header( 'X-Robots-Tag: all' );
		echo self::generate(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
		exit;
	}

	/**
	 * Builds the llms.txt body from real, currently-published content only:
	 * site identity, every published `service` post (name, URL, summary,
	 * price chip if one is set), and links to the Services/Quote pages.
	 * Never invents prices, stats or services that aren't in the database.
	 */
	public static function generate(): string {
		$home = home_url( '/' );
		$name = get_bloginfo( 'name' );
		$desc = get_bloginfo( 'description' );

		$lines = [];
		$lines[] = '# ' . $name;
		$lines[] = '';
		if ( $desc ) {
			$lines[] = '> ' . $desc;
			$lines[] = '';
		}
		$lines[] = 'Website: ' . $home;
		if ( defined( 'ARQAM_CONTACT_EMAIL' ) && ARQAM_CONTACT_EMAIL ) {
			$lines[] = 'Contact: ' . ARQAM_CONTACT_EMAIL;
		}
		$lines[] = '';

		// ── Services (live `service` CPT — title, URL, summary, price) ──
		$services = get_posts( [
			'post_type'      => 'service',
			'posts_per_page' => -1,
			'post_status'    => 'publish',
			'orderby'        => 'menu_order date',
			'order'          => 'ASC',
			'suppress_filters' => false,
		] );

		if ( $services ) {
			$lines[] = '## Services';
			$lines[] = '';
			foreach ( $services as $service ) {
				$sid     = $service->ID;
				$title   = wp_strip_all_tags( get_the_title( $sid ) );
				$url     = get_permalink( $sid );
				$summary = function_exists( 'arqamweb_sp_text' ) ? arqamweb_sp_text( 'sp_summary', $sid ) : '';
				$summary = $summary ?: wp_strip_all_tags( get_the_excerpt( $sid ) );
				$price   = function_exists( 'arqamweb_sp_text' ) ? arqamweb_sp_text( 'sp_card_price', $sid ) : '';

				$entry = '- [' . $title . '](' . $url . ')';
				if ( $summary ) {
					$entry .= ': ' . $summary;
				}
				if ( $price ) {
					$entry .= ' (' . $price . ')';
				}
				$lines[] = $entry;
			}
			$lines[] = '';
		}

		// ── Pricing / quote links — only pages that already exist on the site ──
		$lines[] = '## Pricing & quotes';
		$lines[] = '';
		if ( defined( 'ARQAM_SERVICES_PAGE_SLUG' ) ) {
			$services_url = arqamweb_get_page_permalink( ARQAM_SERVICES_PAGE_SLUG );
			if ( $services_url ) {
				$lines[] = '- All services & published prices: ' . $services_url;
			}
		}
		if ( defined( 'ARQAM_QUOTE_PAGE_SLUG' ) ) {
			$quote_url = arqamweb_get_page_permalink( ARQAM_QUOTE_PAGE_SLUG );
			if ( $quote_url ) {
				$lines[] = '- Request a custom quote: ' . $quote_url;
			}
		}
		if ( defined( 'ARQAM_PROJECTS_PAGE_SLUG' ) ) {
			$projects_url = arqamweb_get_page_permalink( ARQAM_PROJECTS_PAGE_SLUG );
			if ( $projects_url ) {
				$lines[] = '- Past projects: ' . $projects_url;
			}
		}
		if ( defined( 'ARQAM_CONTACT_PAGE_SLUG' ) ) {
			$contact_url = arqamweb_get_page_permalink( ARQAM_CONTACT_PAGE_SLUG );
			if ( $contact_url ) {
				$lines[] = '- Contact: ' . $contact_url;
			}
		}
		$lines[] = '';
		$lines[] = '## Blog';
		$lines[] = '';
		$lines[] = '- ' . get_post_type_archive_link( 'post' );
		$lines[] = '';
		$lines[] = '---';
		$lines[] = 'Generated dynamically from live site content at request time (' . gmdate( 'Y-m-d\TH:i:s\Z' ) . ' UTC). Always current — not a static snapshot.';

		return implode( "\n", $lines ) . "\n";
	}
}
